#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX(a,b) ((a) > (b) ? (a) : (b))

typedef struct ListNode{
    int ele;
    struct ListNode* next;
} ListNode;

typedef struct {
    int size;
    ListNode* head;
    ListNode* tail;
} LinkedList;

LinkedList* new_LinkedList();
void addLast_LinkedList(LinkedList* link, int ele);
int removeFirst_LinkedList(LinkedList* link);

int main() {
    char s[100000];
    gets(s);

    int maxLen = -1;
    int hasLetter = 0;

    int l = 0;
    int r = 0;

    LinkedList* letterIdx = new_LinkedList();

    int len = strlen(s);
    while(r < len) {
        char c = s[r];

        if((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) {
            hasLetter = 1;
            addLast_LinkedList(letterIdx, r);

            if(letterIdx->size > 1) {
                l = removeFirst_LinkedList(letterIdx) + 1;
            }

            if(r == l) {
                r++;
                continue;
            }
        }

        maxLen = MAX(maxLen, r - l + 1);
        r++;
    }

    if(!hasLetter) {
        puts("-1");
    } else {
        printf("%d\n", maxLen);
    }


    return 0;
}

LinkedList* new_LinkedList() {
    LinkedList* link = (LinkedList*) malloc(sizeof(LinkedList));

    link->size = 0;
    link->head = NULL;
    link->tail = NULL;

    return link;
}

void addLast_LinkedList(LinkedList* link, int ele) {
    ListNode* node = (ListNode*) malloc(sizeof(ListNode));

    node->ele = ele;
    node->next = NULL;

    if(link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        link->tail = node;
    }

    link->size++;
}

int removeFirst_LinkedList(LinkedList* link) {
    if(link->size == 0) exit(-1);

    ListNode* removed = link->head;

    if(link->size == 1) {
        link->head = NULL;
        link->tail = NULL;
    } else {
        link->head = link->head->next;
    }

    link->size--;

    int res = removed->ele;

    free(removed);

    return res;
}
